function gradeMatrix(snap){
  const bands=snap.sizeBands||[],rules=snap.gradingRules||[],baseCode=snap.style.base_size||null;
  const out={baseSize:baseCode,sizingMode:snap.style.sizing_mode||'STANDARD',bands,rows:[],warnings:[]};
  if(!baseCode)out.warnings.push('Base size is TBC. No graded production values are authoritative until a base size is confirmed.');
  if(!bands.length)out.warnings.push('No size/weight bands defined.');
  for(const m of snap.measurements||[]){
    const row={code:m.code,name:m.name,nameEn:m.name_en||'',baseValue:m.value,unit:m.unit||'cm',state:m.state,values:{}};
    for(const b of bands){
      const r=rules.find(x=>x.measurement_code===m.code&&x.target_size_code===b.code);
      row.values[b.code]=r&&m.value!=null?{value:Number(m.value)+Number(r.delta_value),delta:Number(r.delta_value),state:r.state,provenance:r.provenance}:{value:null,delta:null,state:'TBC',provenance:'UNKNOWN'};
    }
    out.rows.push(row);
  }
  return out;
}
function patternValidation(snap){
  const pieces=snap.patternPieces||[],links=snap.patternLinks||[],codes=new Set(pieces.map(x=>x.code));const errors=[],warnings=[];
  for(const x of pieces){if(x.qty!=null&&Number(x.qty)<=0)errors.push(`${x.code}: cut quantity must be > 0`);if(x.mirror&&x.on_fold)errors.push(`${x.code}: Mirror and On Fold cannot both be true`);if(!x.grainline||String(x.grainline).toUpperCase()==='TBC')warnings.push(`${x.code}: grainline TBC`);if(['TBC','DRAFT','AI_DRAFT'].includes(String(x.state||'')))warnings.push(`${x.code}: state ${x.state||'DRAFT'}`);}
  for(const l of links){if(!codes.has(l.from_code))errors.push(`Pattern link source missing: ${l.from_code}`);if(!codes.has(l.to_code))errors.push(`Pattern link target missing: ${l.to_code}`);if(l.from_code===l.to_code)warnings.push(`Self-link on ${l.from_code}: ${l.relation}`);}
  if(!links.length)warnings.push('No pattern relationships registered.');
  return {ready:errors.length===0&&warnings.length===0,errors,warnings,pieceCount:pieces.length,linkCount:links.length};
}
function cleanState(v){return String(v||'').toUpperCase();}
function textHasTbc(...values){return values.some(v=>/\bTBC\b|غير مؤكد|حسب العينة|UNKNOWN/i.test(String(v||'')));}
const REQUIREMENT_APPLICABILITY=['REQUIRED','OPTIONAL','NOT_APPLICABLE'];
const REQUIREMENT_STATUSES=['OPEN','SATISFIED','WAIVED'];
function requirementAutoSatisfied(snap,key){
  const k=String(key||'').toUpperCase(),roles=new Set((snap.assets||[]).map(x=>cleanState(x.role)));
  if(k==='CORE_REFERENCE')return Boolean((snap.assets||[]).some(x=>x.id===snap.style?.hero_asset_id||['HERO','REFERENCE'].includes(cleanState(x.role))));
  if(k==='CORE_POM')return (snap.measurements||[]).length>0;
  if(k==='CORE_PATTERN')return (snap.patternPieces||[]).length>0;
  if(k==='CORE_BOM')return (snap.bom||[]).length>0;
  if(k==='CORE_OPERATIONS')return (snap.operations||[]).length>0;
  if(k==='CORE_TECHNICAL_VIEWS')return roles.has('TECHNICAL_FRONT')&&roles.has('TECHNICAL_BACK');
  return false;
}
function requirementGate(snap){
  const rows=(snap.requirements||[]).map(x=>{const auto=requirementAutoSatisfied(snap,x.req_key),effective=auto?'SATISFIED':cleanState(x.status||'OPEN');return {...x,autoSatisfied:auto,effectiveStatus:effective};});
  const matrixExists=rows.length>0,required=rows.filter(x=>cleanState(x.applicability)==='REQUIRED'),blockers=required.filter(x=>x.effectiveStatus==='OPEN'),waived=required.filter(x=>x.effectiveStatus==='WAIVED'),optionalOpen=rows.filter(x=>cleanState(x.applicability)==='OPTIONAL'&&x.effectiveStatus==='OPEN');
  return {matrixExists,ready:!matrixExists||blockers.length===0,blockerCount:blockers.length,requiredCount:required.length,waivedCount:waived.length,optionalOpenCount:optionalOpen.length,blockers:blockers.map(x=>({reqKey:x.req_key,label:x.label,labelEn:x.label_en,linkedRef:x.linked_ref})),items:rows};
}
function releaseGate(snap,releaseType='SAMPLE',options={}){
  const type=String(releaseType||'SAMPLE').toUpperCase(),production=type==='PRODUCTION',blockers=[],warnings=[],checks=[];
  const add=(level,code,message,meta={})=>{const x={level,code,message,...meta};(level==='BLOCKER'?blockers:warnings).push(x);checks.push(x)};
  if(!snap.measurements?.length)add('BLOCKER','POM_EMPTY','No measurements / POM registered.');
  const badPom=(snap.measurements||[]).filter(x=>x.value==null||!['LOCKED','APPROVED'].includes(cleanState(x.state)));
  if(badPom.length)add(production?'BLOCKER':'WARNING','POM_UNAPPROVED',`${badPom.length} POM rows are not APPROVED/LOCKED`,{items:badPom.map(x=>x.code)});
  const unresolvedDna=(snap.dna||[]).filter(x=>cleanState(x.provenance)==='UNKNOWN'||['DRAFT','AI_DRAFT','TBC'].includes(cleanState(x.state))||textHasTbc(x.value_text));
  if(unresolvedDna.length)add(production?'BLOCKER':'WARNING','DNA_TBC',`${unresolvedDna.length} garment DNA fields remain TBC/UNKNOWN`,{items:unresolvedDna.map(x=>x.field_key)});
  const unresolvedBom=(snap.bom||[]).filter(x=>cleanState(x.provenance)==='UNKNOWN'||['DRAFT','AI_DRAFT','TBC'].includes(cleanState(x.status))||textHasTbc(x.specification,x.specification_en));
  if(unresolvedBom.length)add(production?'BLOCKER':'WARNING','BOM_TBC',`${unresolvedBom.length} BOM items remain TBC/UNKNOWN`,{items:unresolvedBom.map(x=>x.code)});
  const pv=patternValidation(snap);for(const e of pv.errors)add('BLOCKER','PATTERN_ERROR',e);for(const w of pv.warnings)add(production?'BLOCKER':'WARNING','PATTERN_WARNING',w);
  if(!(snap.operations||[]).length)add('BLOCKER','OPERATIONS_EMPTY','Operation bulletin is empty.');
  const unapprovedOps=(snap.operations||[]).filter(x=>!['APPROVED','LOCKED'].includes(cleanState(x.state)));
  if(unapprovedOps.length)add(production?'BLOCKER':'WARNING','OPERATIONS_UNAPPROVED',`${unapprovedOps.length} operations are not approved`,{items:unapprovedOps.map(x=>x.seq)});
  const hero=(snap.assets||[]).find(x=>x.id===snap.style.hero_asset_id)||(snap.assets||[]).find(x=>['HERO','REFERENCE'].includes(cleanState(x.role)));
  if(!hero)add('WARNING','REFERENCE_MISSING','No hero/reference image is attached.');
  const prodMarker=(snap.assets||[]).some(x=>cleanState(x.role)==='PRODUCTION_MARKER'),studyMarker=(snap.assets||[]).some(x=>cleanState(x.role)==='MARKER_STUDY');
  if(production&&!prodMarker)add('WARNING','PRODUCTION_MARKER_MISSING',studyMarker?'Only Marker Study exists; it is not a Production Marker.':'No Production Marker asset attached.');
  const bilingualMissing=[...(snap.measurements||[]).filter(x=>!x.name_en),...(snap.bom||[]).filter(x=>!x.name_en),...(snap.operations||[]).filter(x=>!x.name_en)];
  if(bilingualMissing.length)add('WARNING','BILINGUAL_INCOMPLETE',`${bilingualMissing.length} bilingual labels are incomplete.`);
  if(production&&!options.sourceVersionNo&&!(snap.versions||[]).length)add('BLOCKER','VERSION_REQUIRED','Production release requires a frozen Style Version.');
  if(production&&options.sourceVersionNo){const relSamples=(snap.samples||[]).filter(x=>Number(x.version_no)===Number(options.sourceVersionNo));if(relSamples.length&&!relSamples.some(x=>cleanState(x.status)==='APPROVED'))add('BLOCKER','SAMPLE_NOT_APPROVED','Sample rounds exist for the source version but none is APPROVED.');const cs=(snap.costSheets||[]).filter(x=>x.version_no==null||Number(x.version_no)===Number(options.sourceVersionNo));if(cs.length&&!cs.some(x=>cleanState(x.status)==='APPROVED'))add('BLOCKER','COSTING_NOT_APPROVED','Costing exists for the source version but no cost sheet is APPROVED.');}const rg=requirementGate(snap);if(rg.matrixExists&&rg.blockerCount)add(production?'BLOCKER':'WARNING','REQUIREMENTS_OPEN',`${rg.blockerCount} required technical requirements remain OPEN`,{items:rg.blockers.map(x=>x.reqKey)});if(rg.matrixExists&&rg.optionalOpenCount)add('WARNING','OPTIONAL_REQUIREMENTS_OPEN',`${rg.optionalOpenCount} optional requirements remain OPEN.`);
  return {releaseType:type,ready:blockers.length===0,blockerCount:blockers.length,warningCount:warnings.length,blockers,warnings,checks,metrics:{lockedPom:(snap.measurements||[]).filter(x=>cleanState(x.state)==='LOCKED').length,pom:(snap.measurements||[]).length,bom:(snap.bom||[]).length,patternPieces:(snap.patternPieces||[]).length,operations:(snap.operations||[]).length,assets:(snap.assets||[]).length,versions:(snap.versions||[]).length,requirements:(snap.requirements||[]).length,samples:(snap.samples||[]).length,costSheets:(snap.costSheets||[]).length,productionLots:(snap.productionLots||[]).length},requirements:rg};
}
function sampleMeasurementResult(spec,actual,plus,minus){if(actual==null||spec==null)return {result:'PENDING',delta:null};const d=Number(actual)-Number(spec);if(plus==null||minus==null)return {result:'NO_TOLERANCE',delta:d};return {result:(d<=Number(plus)&&d>=-Number(minus))?'PASS':'FAIL',delta:d};}
async function sampleDetail(env,sampleId){const sample=await q1(env,'SELECT * FROM sample_rounds WHERE id=?',sampleId);if(!sample)return null;const measurements=await qall(env,'SELECT * FROM sample_measurements WHERE sample_id=? ORDER BY measurement_code',sampleId);const counts={total:measurements.length,pending:measurements.filter(x=>['PENDING','NO_TOLERANCE'].includes(cleanState(x.result))).length,fail:measurements.filter(x=>cleanState(x.result)==='FAIL').length,pass:measurements.filter(x=>cleanState(x.result)==='PASS').length};return {sample,measurements,counts,readyForApproval:measurements.some(x=>x.actual_value!=null)&&counts.fail===0&&measurements.filter(x=>x.actual_value!=null).every(x=>cleanState(x.result)==='PASS')};}
function costSummary(sheet,lines=[]){const material=lines.reduce((a,x)=>a+(x.line_total==null?0:Number(x.line_total)),0),labor=sheet?.labor_cost==null?null:Number(sheet.labor_cost),over=sheet?.overhead_pct==null?null:Number(sheet.overhead_pct),base=material+(labor||0),overhead=over==null?null:base*over/100,total=(!lines.length||labor==null||over==null||lines.some(x=>x.qty==null||x.unit_cost==null))?null:base+overhead;return {material,labor,overheadPct:over,overhead,total,complete:total!=null};}
