  let sh=versionNo==null?null:await q1(env,"SELECT * FROM cost_sheets WHERE style_id=? AND status='APPROVED' AND version_no=? ORDER BY approved_at DESC LIMIT 1",styleId,versionNo);if(!sh)sh=await q1(env,"SELECT * FROM cost_sheets WHERE style_id=? AND status='APPROVED' AND version_no IS NULL ORDER BY approved_at DESC LIMIT 1",styleId);
  if(!sh)return {available:false,reason:'NO_APPROVED_COST_SHEET',sourceVersionNo:versionNo,lines:[]};const lines=await qall(env,'SELECT source_type,source_ref,description,qty,unit,unit_cost,waste_pct FROM cost_lines WHERE cost_sheet_id=? ORDER BY created_at',sh.id);
