function stableComparable(v){if(v===undefined)return null;if(v===null||typeof v!=='object')return v;if(Array.isArray(v))return v.map(stableComparable);const out={};for(const k of Object.keys(v).sort())if(!['id','created_at','updated_at','created_by','versions','releases','variants','variantOf'].includes(k))out[k]=stableComparable(v[k]);return out;}
