async function membershipRole(env,sess,orgId){if(sess.platformAdmin)return 'PLATFORM_ADMIN';const m=await q1(env,'SELECT role FROM memberships WHERE user_id=? AND org_id=?',sess.userId,orgId);if(!m)throw Object.assign(new Error('Forbidden workspace'),{status:403});return String(m.role||'').toUpperCase();}
