function analysisPrompt(context){return `You are the multimodal apparel-analysis stage of SEHHA ApparelOS. Return JSON only, with no markdown.\nYou are assisting professional fashion designers, pattern makers and factories. Analyze what is visually supported across one or more supplied images, but never invent production facts. If images conflict, report the conflict and require human review rather than choosing silently.\nEvery claim must be OBSERVED, INFERRED or UNKNOWN. Exact measurements, GSM, fiber composition, zipper length, seam allowance, shrinkage, grade rules and physical fabric performance must remain UNKNOWN unless visible text or supplied context explicitly proves them.\nDistinguish garment construction from artwork/print. Detect if the image contains one garment, a set, or multiple colorways.\nReturn exactly this JSON structure:\n{"garment":{"family":"","type":"","audience":"","constructionMode":"","fit":"","multiGarment":false,"colorwayCount":1},"features":[{"key":"","label":"","value":"","confidence":0.0,"provenance":"OBSERVED|INFERRED|UNKNOWN"}],"detectedDetails":[""],"materialAppearance":{"family":"","surface":"","nap":"YES|NO|UNKNOWN","stretch":"UNKNOWN","composition":"UNKNOWN","gsm":"UNKNOWN"},"trims":[{"name":"","count":null,"confidence":0.0,"provenance":"OBSERVED|INFERRED|UNKNOWN"}],"artwork":[{"zone":"","description":"","confidence":0.0}],"segments":[{"assetId":"","label":"","labelEn":"","bbox":[0.0,0.0,0.0,0.0],"confidence":0.0,"provenance":"OBSERVED|INFERRED|UNKNOWN"}],"templateCandidates":[{"template":"","confidence":0.0,"reason":""}],"suggestedPOM":[{"code":"","name":"","reason":""}],"suggestedPatternArchitecture":[{"code":"","name":"","qty":null,"note":""}],"suggestedOperations":[{"seq":1,"name":"","machine":"","stitch":"","qc":""}],"conflicts":[{"field":"","assetIds":[],"reason":""}],"sourceAssets":[],"warnings":[""]}\nFor segments, bbox is normalized [x,y,w,h] from 0 to 1 and must only mark visually supported regions. Do not invent hidden geometry.\nApplication context: ${JSON.stringify(context)}`;}
function stripJsonFence(txt){const t=String(txt||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();const a=t.indexOf('{'),b=t.lastIndexOf('}');return a>=0&&b>a?t.slice(a,b+1):t;}
