function garmentTemplateProfile(input){
  const style=input?.style||input||{},raw=String(style.garment_type||'CUSTOM').toUpperCase();
  if(GARMENT_TEMPLATE_PROFILES[raw])return GARMENT_TEMPLATE_PROFILES[raw];
  if(/JACKET|COAT|BLAZER/.test(raw))return {...GARMENT_TEMPLATE_PROFILES.CUSTOM,id:raw,family:'JACKET',labelEn:'Jacket / Outerwear',labelAr:'جاكيت / ملابس خارجية',detailKind:'CLOSURE'};
  if(/PANT|TROUSER|SHORT/.test(raw))return {...GARMENT_TEMPLATE_PROFILES.CUSTOM,id:raw,family:'PANTS',labelEn:'Pants / Bottom',labelAr:'بنطلون / قطعة سفلية',detailKind:'WAIST_CLOSURE'};
  if(/DRESS|GOWN/.test(raw))return {...GARMENT_TEMPLATE_PROFILES.DRESS,id:raw};
  return {...GARMENT_TEMPLATE_PROFILES.CUSTOM,id:raw};
}
